cat > src/base64.c <<'EOF'
#include "brotli.h"
#include <string.h>

static int b64_val(char c) {
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
    if (c >= '0' && c <= '9') return c - '0' + 52;
    if (c == '+' || c == '-') return 62;
    if (c == '/' || c == '_') return 63;
    return -1;
}

int base64_decode(const char *src, size_t src_len, uint8_t *dst, size_t dst_max) {
    size_t out = 0;
    int buf = 0;
    int bits = 0;
    for (size_t i = 0; i < src_len; i++) {
        char c = src[i];
        if (c == '=' || c == '\n' || c == '\r') continue;
        int v = b64_val(c);
        if (v < 0) return -1;
        buf = (buf << 6) | v;
        bits += 6;
        if (bits >= 8) {
            bits -= 8;
            if (out >= dst_max) return -1;
            dst[out++] = (uint8_t)((buf >> bits) & 0xff);
        }
    }
    return (int)out;
}
