#include "brotli.h"
#include <stdlib.h>
#include <string.h>

/*
 * Minimal Brotli encoder producing only uncompressed meta-blocks.
 * This is fully compliant with RFC 7932: uncompressed meta-blocks are a
 * valid Brotli construct. Output can be decoded by any compliant decoder.
 *
 * Stream layout:
 *   WBITS header (1 bit = 0 => wbits = 16)
 *   Zero or more uncompressed non-last meta-blocks carrying chunks up to
 *   2**24 bytes.
 *   Optional metadata meta-block carrying the comment.
 *   Final empty meta-block (ISLAST=1, ISLASTEMPTY=1).
 */

typedef struct {
    FILE *out;
    uint32_t buf;
    int bits;
} BitWriter;

static void bw_init(BitWriter *bw, FILE *out) {
    bw->out = out;
    bw->buf = 0;
    bw->bits = 0;
}

static void bw_put(BitWriter *bw, uint32_t val, int nbits) {
    bw->buf |= (val & ((1u << nbits) - 1u)) << bw->bits;
    bw->bits += nbits;
    while (bw->bits >= 8) {
        uint8_t b = (uint8_t)(bw->buf & 0xff);
        fwrite(&b, 1, 1, bw->out);
        bw->buf >>= 8;
        bw->bits -= 8;
    }
}

static void bw_align(BitWriter *bw) {
    if (bw->bits > 0) {
        uint8_t b = (uint8_t)(bw->buf & 0xff);
        fwrite(&b, 1, 1, bw->out);
        bw->buf = 0;
        bw->bits = 0;
    }
}

static void bw_write_bytes(BitWriter *bw, const uint8_t *data, size_t len) {
    /* Assume byte-aligned */
    fwrite(data, 1, len, bw->out);
}

/* Write WBITS header.
 * We use wbits = 16, encoded as a single 0 bit. */
static void write_wbits(BitWriter *bw) {
    bw_put(bw, 0, 1);  /* wbits = 16 */
}

/* Write an uncompressed non-last meta-block carrying len bytes of data.
 * Requires 1 <= len <= 2**24. */
static void write_uncompressed_block(BitWriter *bw, const uint8_t *data,
                                     uint32_t len) {
    uint32_t mlen_m1 = len - 1;
    /* ISLAST = 0 */
    bw_put(bw, 0, 1);
    /* Choose MNIBBLES based on length */
    int mnibbles;
    if (mlen_m1 < (1u << 16))      mnibbles = 4;
    else if (mlen_m1 < (1u << 20)) mnibbles = 5;
    else                           mnibbles = 6;
    /* Encoding: 0 => 4, 1 => 5, 2 => 6, 3 => metadata */
    bw_put(bw, (uint32_t)(mnibbles - 4), 2);
    bw_put(bw, mlen_m1, mnibbles * 4);
    /* ISUNCOMPRESSED = 1 */
    bw_put(bw, 1, 1);
    /* Pad to byte boundary */
    bw_align(bw);
    /* Write data */
    bw_write_bytes(bw, data, len);
}

/* Metadata meta-block carrying a comment up to 80 bytes.
 * MNIBBLES=0 marker: 2 bits = 11 (value 3)
 * RESERVED: 1 bit = 0
 * MSKIPBYTES: 2 bits
 * MSKIPLEN: MSKIPBYTES*8 bits (metadata length - 1, little endian)
 * Skip to byte boundary
 * Copy MSKIPLEN+1 metadata bytes.
 * If length == 0, MSKIPBYTES = 0 (no MSKIPLEN; no data). */
static void write_metadata_block(BitWriter *bw, const uint8_t *data,
                                 size_t len) {
    /* ISLAST = 0 */
    bw_put(bw, 0, 1);
    /* MNIBBLES = 0 (metadata marker), encoded as value 3 */
    bw_put(bw, 3, 2);
    /* RESERVED = 0 */
    bw_put(bw, 0, 1);
    int mskipbytes;
    if (len == 0) mskipbytes = 0;
    else if (len <= 0x100) mskipbytes = 1;
    else if (len <= 0x10000) mskipbytes = 2;
    else mskipbytes = 3;
    bw_put(bw, (uint32_t)mskipbytes, 2);
    if (len > 0) {
        bw_put(bw, (uint32_t)(len - 1), mskipbytes * 8);
    }
    /* Align */
    bw_align(bw);
    if (len > 0) bw_write_bytes(bw, data, len);
}

/* Final empty meta-block. */
static void write_last_empty(BitWriter *bw) {
    bw_put(bw, 1, 1); /* ISLAST */
    bw_put(bw, 1, 1); /* ISLASTEMPTY */
    bw_align(bw);
}

int brotli_encode_file(FILE *in, FILE *out, int lgwin, int large_window,
                       const uint8_t *comment, size_t comment_len) {
    (void)lgwin;
    (void)large_window;
    BitWriter bw;
    bw_init(&bw, out);
    write_wbits(&bw);

    if (comment && comment_len > 0) {
        write_metadata_block(&bw, comment, comment_len);
    }

    /* Read input in chunks and emit non-last uncompressed meta-blocks. */
    const size_t CHUNK = 1u << 20; /* 1 MB per meta-block for simplicity */
    uint8_t *buf = (uint8_t *)malloc(CHUNK);
    if (!buf) return -1;
    for (;;) {
        size_t n = fread(buf, 1, CHUNK, in);
        if (n == 0) break;
        write_uncompressed_block(&bw, buf, (uint32_t)n);
    }
    free(buf);
    write_last_empty(&bw);
    return 0;
}
