#include "brotli.h"
#include <stdlib.h>
#include <string.h>

/*
 * Minimal Brotli decoder supporting:
 *   - WBITS header parsing
 *   - Empty last meta-block (ISLASTEMPTY)
 *   - Uncompressed meta-blocks (ISUNCOMPRESSED=1)
 *   - Metadata meta-blocks (MNIBBLES=0)
 *   - Concatenated streams when enabled
 *   - Optional comment verification
 */

typedef struct {
    FILE *in;
    uint32_t buf;
    int bits;     /* bits currently available in buf */
    int eof;
} BitReader;

static void br_init(BitReader *br, FILE *in) {
    br->in = in;
    br->buf = 0;
    br->bits = 0;
    br->eof = 0;
}

/* Read up to 24 bits; returns -1 on error. */
static int br_read(BitReader *br, int nbits, uint32_t *out) {
    while (br->bits < nbits) {
        int c = fgetc(br->in);
        if (c == EOF) {
            return -1;
        }
        br->buf |= ((uint32_t)(uint8_t)c) << br->bits;
        br->bits += 8;
    }
    *out = br->buf & ((1u << nbits) - 1u);
    br->buf >>= nbits;
    br->bits -= nbits;
    return 0;
}

/* Peek end-of-stream check: returns 1 if no more bits available. */
static int br_at_eof(BitReader *br) {
    if (br->bits > 0) {
        /* Require that all remaining bits are zero (padding). Not strictly
         * validated here. */
        int c = fgetc(br->in);
        if (c == EOF) return 1;
        br->buf |= ((uint32_t)(uint8_t)c) << br->bits;
        br->bits += 8;
        return 0;
    }
    int c = fgetc(br->in);
    if (c == EOF) return 1;
    ungetc(c, br->in);
    return 0;
}

/* Align input to byte boundary, discarding padding bits. */
static int br_align(BitReader *br) {
    int pad = br->bits & 7;
    if (pad > 0) {
        uint32_t v;
        if (br_read(br, pad, &v) < 0) return -1;
        /* Padding must be zero per RFC, but we don't strictly enforce. */
    }
    return 0;
}

/* Read n bytes directly (after alignment). */
static int br_read_bytes(BitReader *br, uint8_t *dst, size_t len) {
    /* First drain buffered whole bytes */
    while (len > 0 && br->bits >= 8) {
        *dst++ = (uint8_t)(br->buf & 0xff);
        br->buf >>= 8;
        br->bits -= 8;
        len--;
    }
    if (br->bits != 0) return -1; /* Not byte aligned */
    while (len > 0) {
        size_t got = fread(dst, 1, len, br->in);
        if (got == 0) return -1;
        dst += got;
        len -= got;
    }
    return 0;
}

/* Read WBITS. Returns wbits on success, -1 on error. */
static int read_wbits(BitReader *br, int large_window) {
    uint32_t b;
    if (br_read(br, 1, &b) < 0) return -1;
    if (b == 0) return 16;
    uint32_t n;
    if (br_read(br, 3, &n) < 0) return -1;
    if (n != 0) {
        /* value 1-7 => wbits 17-23 */
        return 17 + (int)n - 1 + ((int)n == 0 ? 0 : 0);
    }
    /* Large window uses an extended range; read 3 more bits */
    uint32_t m;
    if (br_read(br, 3, &m) < 0) return -1;
    if (m == 0) {
        /* reserved, but some encoders use this for wbits = 17 */
        return -1;
    }
    /* value 1-7 after 000 => wbits 8-14 (or invalid) */
    int v = 8 + (int)m;
    (void)large_window;
    return v;
}

static int decode_single_stream(BitReader *br, FILE *out, int large_window,
                                const uint8_t *expected_comment,
                                size_t expected_comment_len,
                                int check_comment,
                                int *found_comment) {
    int wbits = read_wbits(br, large_window);
    if (wbits < 0) return -1;

    for (;;) {
        uint32_t islast;
        if (br_read(br, 1, &islast) < 0) return -1;
        if (islast) {
            uint32_t islastempty;
            if (br_read(br, 1, &islastempty) < 0) return -1;
            if (islastempty) {
                /* Align; stream ends */
                if (br_align(br) < 0) return -1;
                return 0;
            }
        }
        uint32_t mnibbles_code;
        if (br_read(br, 2, &mnibbles_code) < 0) return -1;
        if (mnibbles_code == 3) {
            /* Metadata block */
            if (islast) return -1; /* metadata can't be last with data */
            uint32_t reserved;
            if (br_read(br, 1, &reserved) < 0) return -1;
            if (reserved != 0) return -1;
            uint32_t mskipbytes;
            if (br_read(br, 2, &mskipbytes) < 0) return -1;
            uint32_t mskiplen = 0;
            if (mskipbytes > 0) {
                if (br_read(br, (int)mskipbytes * 8, &mskiplen) < 0) return -1;
                /* Check high byte non-zero per RFC */
            }
            if (br_align(br) < 0) return -1;
            uint32_t meta_len = (mskipbytes == 0) ? 0 : (mskiplen + 1);
            if (meta_len > 0) {
                uint8_t *mbuf = (uint8_t *)malloc(meta_len);
                if (!mbuf) return -1;
                if (br_read_bytes(br, mbuf, meta_len) < 0) {
                    free(mbuf);
                    return -1;
                }
                if (check_comment) {
                    if (!*found_comment) {
                        if (expected_comment_len == meta_len &&
                            memcmp(expected_comment, mbuf, meta_len) == 0) {
                            *found_comment = 1;
                        }
                    }
                }
                free(mbuf);
            } else if (check_comment && expected_comment_len == 0) {
                *found_comment = 1;
            }
            continue;
        }
        int mnibbles = 4 + (int)mnibbles_code;
        uint32_t mlen_m1;
        if (br_read(br, mnibbles * 4, &mlen_m1) < 0) return -1;
        uint32_t mlen = mlen_m1 + 1;
        uint32_t isuncompressed = 0;
        if (!islast) {
            if (br_read(br, 1, &isuncompressed) < 0) return -1;
        }
        if (!isuncompressed) {
            /* Compressed meta-block: not supported in this minimal decoder. */
            return -2; /* flag: needs full decoder */
        }
        if (br_align(br) < 0) return -1;
        uint8_t *dbuf = (uint8_t *)malloc(mlen);
        if (!dbuf) return -1;
        if (br_read_bytes(br, dbuf, mlen) < 0) {
            free(dbuf);
            return -1;
        }
        if (fwrite(dbuf, 1, mlen, out) != mlen) {
            free(dbuf);
            return -1;
        }
        free(dbuf);
        if (islast) {
            if (br_align(br) < 0) return -1;
            return 0;
        }
    }
}

int brotli_decode_stream(FILE *in, FILE *out, int concatenated, int large_window,
                         const uint8_t *expected_comment, size_t expected_comment_len,
                         int check_comment) {
    BitReader br;
    br_init(&br, in);
    int found_comment = (check_comment && expected_comment_len == 0) ? 0 : 0;
    /* Check for truly empty input: feof before any read */
    int first = fgetc(in);
    if (first == EOF) {
        return -1;
    }
    ungetc(first, in);
    for (;;) {
        int rc = decode_single_stream(&br, out, large_window,
                                      expected_comment, expected_comment_len,
                                      check_comment, &found_comment);
        if (rc != 0) return rc;
        if (!concatenated) break;
        /* Check if there's more input */
        int c = fgetc(in);
        if (c == EOF) break;
        ungetc(c, in);
        br_init(&br, in);
    }
    /* Ensure no trailing bytes when not concatenated */
    if (!concatenated) {
        /* drain bits buffer already consumed in align; check stream */
        int c = fgetc(in);
        if (c != EOF) {
            /* Extra data - ok, some tools allow it. Don't fail. */
            ungetc(c, in);
        }
    }
    if (check_comment && !found_comment) return -3;
    return 0;
}
