#include <time.h>
#include <utime.h>
#include <ctype.h>

static const char *USAGE_HEAD = "Usage: %s [OPTION]... [FILE]...\n";

static const char *USAGE_BODY =
"Options:\n"
"  -#                          compression level (0-9)\n"
"  -c, --stdout                write on standard output\n"
