"All arguments after '--' are treated as files.\n";

static const char *PROG = "executable";

static void print_usage(FILE *f) {
    fprintf(f, USAGE_HEAD, PROG);
    fputs(USAGE_BODY, f);
}

typedef enum { CMD_NONE = 0, CMD_COMPRESS, CMD_DECOMPRESS, CMD_TEST } Command;

typedef struct {
    Command command;
    int command_set;     /* whether command was explicitly set */
    int to_stdout;
    int force;
    int keep_set;        /* -k or -j set */
    int remove_source;   /* -j */
    int squash;          /* -s */
    int no_copy_stat;    /* -n */
    int verbose;
    int verbose_set;
    int concatenated;
    int quality;         /* -1 means not set */
    int quality_set;
    int lgwin;           /* -1 means not set */
    int lgwin_set;
    int large_window;    /* -1 means not set */
    int large_window_set;
    const char *output;
    const char *suffix;
    const char *dict_file;
    const char *comment_b64;
    uint8_t comment_decoded[80];
    int comment_len;
    int comment_set;
    char **files;
    int n_files;
} Options;

static void die_usage(const char *fmt, ...) __attribute__((noreturn));
static void die_usage(const char *fmt, ...) {
    va_list ap;
    __builtin_va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    __builtin_va_end(ap);
    fputc('\n', stderr);
    print_usage(stderr);
    exit(1);
}

static int parse_int(const char *s, int *out) {
    if (!s || !*s) return -1;
    char *end;
    long v = strtol(s, &end, 10);
    if (*end != '\0') return -1;
    *out = (int)v;
    return 0;
}

/* Long options list. Each option can have a value specified via '=value' */
static int starts_with(const char *s, const char *prefix) {
    size_t n = strlen(prefix);
    return strncmp(s, prefix, n) == 0;
}

static int eq_name(const char *arg, const char *name, const char **val) {
    size_t n = strlen(name);
    if (strncmp(arg, name, n) != 0) return 0;
    if (arg[n] == '\0') { *val = NULL; return 1; }
    if (arg[n] == '=') { *val = arg + n + 1; return 1; }
    return 0;
}

static void opt_init(Options *o) {
    memset(o, 0, sizeof(*o));
    o->command = CMD_COMPRESS;
    o->quality = -1;
    o->lgwin = -1;
    o->large_window = -1;
    o->suffix = ".br";
}

static void set_command(Options *o, Command c, const char *name) {
    if (o->command_set) die_usage("command already set when parsing %s", name);
    o->command = c;
    o->command_set = 1;
}

static void apply_comment(Options *o, const char *b64) {
    if (o->comment_set) die_usage("argument --comment / -C already set");
    o->comment_b64 = b64;
    int len = base64_decode(b64, strlen(b64), o->comment_decoded,
                            sizeof(o->comment_decoded));
    if (len < 0) {
        die_usage("error parsing comment value [%s]", b64);
    }
    o->comment_len = len;
    o->comment_set = 1;
}

static void parse_args(Options *o, int argc, char **argv) {
    int files_only = 0;
    int i = 1;
    /* Count files up front (we fill during parsing). */
    o->files = (char **)calloc(argc + 1, sizeof(char *));
    if (!o->files) { perror("calloc"); exit(1); }
    while (i < argc) {
        const char *arg = argv[i];
        if (files_only) {
            o->files[o->n_files++] = (char *)arg;
            i++;
            continue;
        }
        if (strcmp(arg, "--") == 0) { files_only = 1; i++; continue; }
        if (strcmp(arg, "-") == 0) {
            o->files[o->n_files++] = (char *)arg;
            i++;
            continue;
        }
        if (arg[0] != '-' || arg[1] == '\0') {
            o->files[o->n_files++] = (char *)arg;
            i++;
            continue;
        }
        if (arg[0] == '-' && arg[1] == '-') {
            /* long option */
            const char *val = NULL;
            if (eq_name(arg, "--stdout", &val)) {
                if (val) die_usage("argument --stdout / -c does not accept value");
                if (o->to_stdout) die_usage("argument --stdout / -c already set");
                o->to_stdout = 1;
            } else if (eq_name(arg, "--decompress", &val)) {
                if (val) die_usage("argument --decompress / -d does not accept value");
                set_command(o, CMD_DECOMPRESS, "-d");
            } else if (eq_name(arg, "--force", &val)) {
                if (val) die_usage("argument --force / -f does not accept value");
                if (o->force) die_usage("force output overwrite already set");
                o->force = 1;
            } else if (eq_name(arg, "--help", &val)) {
                if (val) die_usage("argument --help / -h does not accept value");
                print_usage(stdout);
                exit(0);
            } else if (eq_name(arg, "--rm", &val)) {
                if (val) die_usage("argument --rm / -j does not accept value");
                if (o->keep_set) die_usage("argument --rm / -j or --keep / -k already set");
                o->remove_source = 1;
                o->keep_set = 1;
            } else if (eq_name(arg, "--squash", &val)) {
                if (val) die_usage("argument --squash / -s does not accept value");
                if (o->squash) die_usage("argument --squash / -s already set");
                o->squash = 1;
            } else if (eq_name(arg, "--keep", &val)) {
                if (val) die_usage("argument --keep / -k does not accept value");
                if (o->keep_set) die_usage("argument --rm / -j or --keep / -k already set");
                o->keep_set = 1;
            } else if (eq_name(arg, "--no-copy-stat", &val)) {
                if (val) die_usage("argument --no-copy-stat / -n does not accept value");
                if (o->no_copy_stat) die_usage("argument --no-copy-stat / -n already set");
                o->no_copy_stat = 1;
            } else if (eq_name(arg, "--output", &val)) {
                if (!val) die_usage("must pass the parameter as --output=value");
                if (o->output) die_usage("argument --output / -o already set");
                o->output = val;
            } else if (eq_name(arg, "--quality", &val)) {
                if (!val) die_usage("must pass the parameter as --quality=value");
                if (o->quality_set) die_usage("quality already set");
                int q;
                if (parse_int(val, &q) < 0 || q < 0 || q > 11)
                    die_usage("error parsing quality value [%s]", val);
                o->quality = q;
                o->quality_set = 1;
            } else if (eq_name(arg, "--test", &val)) {
                if (val) die_usage("argument --test / -t does not accept value");
                set_command(o, CMD_TEST, "-t");
            } else if (eq_name(arg, "--verbose", &val)) {
                if (val) die_usage("argument --verbose / -v does not accept value");
                if (o->verbose_set) die_usage("argument --verbose / -v already set");
                o->verbose = 1;
                o->verbose_set = 1;
            } else if (eq_name(arg, "--lgwin", &val)) {
                if (!val) die_usage("must pass the parameter as --lgwin=value");
                if (o->lgwin_set) die_usage("lgwin already set");
                int w;
                if (parse_int(val, &w) < 0 || (w != 0 && (w < 10 || w > 24)))
                    die_usage("error parsing lgwin value [%s]", val);
                o->lgwin = w;
                o->lgwin_set = 1;
            } else if (eq_name(arg, "--large_window", &val)) {
                if (!val) die_usage("must pass the parameter as --large_window=value");
                if (o->large_window_set) die_usage("large_window already set");
                int w;
                if (parse_int(val, &w) < 0 || (w != 0 && (w < 10 || w > 30)))
                    die_usage("error parsing large_window value [%s]", val);
                o->large_window = w;
                o->large_window_set = 1;
            } else if (eq_name(arg, "--comment", &val)) {
                if (!val) die_usage("must pass the parameter as --comment=value");
                apply_comment(o, val);
            } else if (eq_name(arg, "--dictionary", &val)) {
                if (!val) die_usage("must pass the parameter as --dictionary=value");
                if (o->dict_file) die_usage("argument --dictionary / -D already set");
                o->dict_file = val;
            } else if (eq_name(arg, "--concatenated", &val)) {
                if (val) die_usage("argument --concatenated / -K does not accept value");
                if (o->concatenated) die_usage("argument --concatenated / -K already set");
                o->concatenated = 1;
            } else if (eq_name(arg, "--suffix", &val)) {
                if (!val) die_usage("must pass the parameter as --suffix=value");
                if (strcmp(o->suffix, ".br") != 0) die_usage("argument --suffix / -S already set");
                o->suffix = val;
            } else if (eq_name(arg, "--version", &val)) {
                if (val) die_usage("argument --version / -V does not accept value");
                printf("brotli 1.2.0\n");
                exit(0);
            } else if (eq_name(arg, "--best", &val)) {
                if (val) die_usage("argument --best / -Z does not accept value");
                if (o->quality_set) die_usage("quality already set");
                o->quality = 11;
                o->quality_set = 1;
            } else {
                die_usage("must pass the parameter as %s=value", arg);
            }
            i++;
            continue;
        }
        /* short options: can be coalesced */
        int j = 1;
        while (arg[j]) {
            char c = arg[j];
            if (c >= '0' && c <= '9') {
                if (o->quality_set) die_usage("quality already set");
                o->quality = c - '0';
                o->quality_set = 1;
                j++;
                continue;
            }
            switch (c) {
                case 'c':
                    if (o->to_stdout) die_usage("argument --stdout / -c already set");
                    o->to_stdout = 1;
                    break;
                case 'd':
                    set_command(o, CMD_DECOMPRESS, "-d");
                    break;
                case 'f':
                    if (o->force) die_usage("force output overwrite already set");
                    o->force = 1;
                    break;
                case 'h':
                    print_usage(stdout);
                    exit(0);
                case 'j':
                    if (o->keep_set) die_usage("argument --rm / -j or --keep / -k already set");
                    o->remove_source = 1;
                    o->keep_set = 1;
                    break;
                case 's':
                    if (o->squash) die_usage("argument --squash / -s already set");
                    o->squash = 1;
                    break;
                case 'k':
                    if (o->keep_set) die_usage("argument --rm / -j or --keep / -k already set");
                    o->keep_set = 1;
                    break;
                case 'n':
                    if (o->no_copy_stat) die_usage("argument --no-copy-stat / -n already set");
                    o->no_copy_stat = 1;
                    break;
                case 't':
                    set_command(o, CMD_TEST, "-t");
                    break;
                case 'v':
                    if (o->verbose_set) die_usage("argument --verbose / -v already set");
                    o->verbose = 1;
                    o->verbose_set = 1;
                    break;
                case 'K':
                    if (o->concatenated) die_usage("argument --concatenated / -K already set");
                    o->concatenated = 1;
                    break;
                case 'V':
                    printf("brotli 1.2.0\n");
                    exit(0);
                case 'Z':
                    if (o->quality_set) die_usage("quality already set");
                    o->quality = 11;
                    o->quality_set = 1;
                    break;
                case 'o': case 'q': case 'w': case 'C': case 'D': case 'S': {
                    /* These take a value - must be the last char (require next argv) */
                    if (arg[j+1] != '\0')
                        die_usage("expected parameter for argument -%c", c);
                    if (i + 1 >= argc)
                        die_usage("expected parameter for argument -%c", c);
                    const char *val = argv[++i];
                    if (c == 'o') {
                        if (o->output) die_usage("argument --output / -o already set");
                        o->output = val;
                    } else if (c == 'q') {
                        if (o->quality_set) die_usage("quality already set");
                        int q;
                        if (parse_int(val, &q) < 0 || q < 0 || q > 11)
                            die_usage("error parsing quality value [%s]", val);
                        o->quality = q;
                        o->quality_set = 1;
                    } else if (c == 'w') {
                        if (o->lgwin_set) die_usage("lgwin already set");
                        int w;
                        if (parse_int(val, &w) < 0 || (w != 0 && (w < 10 || w > 24)))
                            die_usage("error parsing lgwin value [%s]", val);
                        o->lgwin = w;
                        o->lgwin_set = 1;
                    } else if (c == 'C') {
                        apply_comment(o, val);
                    } else if (c == 'D') {
                        if (o->dict_file) die_usage("argument --dictionary / -D already set");
                        o->dict_file = val;
                    } else if (c == 'S') {
                        if (strcmp(o->suffix, ".br") != 0) die_usage("argument --suffix / -S already set");
                        o->suffix = val;
                    }
                    j++;
                    goto next_arg;
                }
                default:
                    die_usage("invalid argument -%c", c);
            }
            j++;
        }
    next_arg:
        i++;
    }
}

/* ---------- File processing ---------- */

static const char *file_display_name(const char *fname) {
    if (!fname || strcmp(fname, "-") == 0) return "con";
    return fname;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int open_input(const char *fname, FILE **fp, const char **display) {
    if (!fname || strcmp(fname, "-") == 0) {
        *fp = stdin;
        *display = "con";
        return 0;
    }
    FILE *f = fopen(fname, "rb");
    if (!f) {
        fprintf(stderr, "failed to open input file [%s]: %s\n", fname,
                strerror(errno));
        return -1;
    }
    *fp = f;
    *display = fname;
    return 0;
}

static int open_output(const char *fname, FILE **fp, int force) {
    if (!fname || strcmp(fname, "-") == 0) {
        *fp = stdout;
        return 0;
    }
    if (!force && file_exists(fname)) {
        fprintf(stderr, "failed to open output file [%s]: File exists\n", fname);
        return -1;
    }
    FILE *f = fopen(fname, "wb");
    if (!f) {
        fprintf(stderr, "failed to open output file [%s]: %s\n", fname,
                strerror(errno));
        return -1;
    }
    *fp = f;
    return 0;
}

/* Get elapsed seconds */
static double monotime(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

static long long file_size(FILE *f) {
    long long pos = ftell(f);
    if (pos < 0) return -1;
    if (fseek(f, 0, SEEK_END) != 0) return -1;
    long long end = ftell(f);
    fseek(f, pos, SEEK_SET);
    return end;
}

/* Copy file stat (mtime & mode) from src to dst. */
static void copy_stat(const char *src, const char *dst) {
    struct stat st;
    if (stat(src, &st) != 0) return;
    struct timespec ts[2];
    ts[0] = st.st_atim;
    ts[1] = st.st_mtim;
    utimensat(AT_FDCWD, dst, ts, 0);
    chmod(dst, st.st_mode & 07777);
}

/* Derive output filename based on command. If compress, append suffix.
 * If decompress/test, strip suffix. Returns 0 on success, -1 on error.
 * out_buf must have room for strlen(fname) + strlen(suffix) + 1. */
static int derive_output_name(const Options *o, const char *fname,
                              char *out_buf, size_t out_cap) {
    size_t flen = strlen(fname);
    size_t slen = strlen(o->suffix);
    if (o->command == CMD_COMPRESS) {
        if (flen + slen + 1 > out_cap) return -1;
        memcpy(out_buf, fname, flen);
        memcpy(out_buf + flen, o->suffix, slen);
        out_buf[flen + slen] = '\0';
        return 0;
    }
    if (o->command == CMD_DECOMPRESS) {
        if (flen <= slen || memcmp(fname + flen - slen, o->suffix, slen) != 0) {
            fprintf(stderr, "input file [%s] suffix mismatch\n", fname);
            return -1;
        }
        size_t newlen = flen - slen;
        if (newlen == 0) {
            fprintf(stderr, "empty output file name for [%s] input file\n", fname);
            return -1;
        }
        if (newlen + 1 > out_cap) return -1;
        memcpy(out_buf, fname, newlen);
        out_buf[newlen] = '\0';
        return 0;
    }
    return -1;
}

static int process_compress(const Options *o, const char *fname) {
    FILE *in = NULL, *out = NULL;
    const char *display = NULL;
    if (open_input(fname, &in, &display) < 0) return 1;

    char derived[4096];
    const char *out_name = NULL;
    if (o->to_stdout) {
        out_name = NULL; /* stdout */
    } else if (o->output) {
        out_name = o->output;
    } else if (!fname || strcmp(fname, "-") == 0) {
        /* Writing stdin to stdout when no output specified. */
        out_name = NULL;
    } else {
        if (derive_output_name(o, fname, derived, sizeof(derived)) < 0) {
            if (in != stdin) fclose(in);
            return 1;
        }
        out_name = derived;
    }
    if (out_name && strcmp(out_name, "-") != 0) {
        if (open_output(out_name, &out, o->force) < 0) {
            if (in != stdin) fclose(in);
            return 1;
        }
    } else {
        out = stdout;
    }

    double t0 = monotime();
    long long in_bytes = 0;
    /* We'll measure input bytes as we read. */
    /* Since encoder reads from FILE*, we need to get size after. For stdin we
     * can buffer or count. Simple: use file size for regular files; count for stdin. */
    long long in_size_known = -1;
    if (in != stdin) {
        struct stat st;
        if (fstat(fileno(in), &st) == 0) in_size_known = st.st_size;
    }

    int rc = brotli_encode_file(in, out,
                                o->lgwin_set ? o->lgwin : 0,
                                o->large_window_set ? o->large_window : -1,
                                o->comment_set ? o->comment_decoded : NULL,
                                o->comment_len);
    double t1 = monotime();
    if (rc != 0) {
        fprintf(stderr, "compression failed\n");
        if (in != stdin) fclose(in);
        if (out != stdout) fclose(out);
        return 1;
    }
    long long out_bytes = 0;
    if (out != stdout) {
        out_bytes = ftell(out);
    }
    if (out != stdout) fclose(out);
    if (in != stdin) {
        in_bytes = in_size_known;
        fclose(in);
    }

    /* Squash: delete output if larger */
    if (o->squash && out != stdout && in_bytes >= 0 && out_bytes > in_bytes) {
        unlink(out_name);
    }

    /* Copy stat if compressing a file to a file */
    if (fname && strcmp(fname, "-") != 0 && out != stdout && !o->no_copy_stat) {
        copy_stat(fname, out_name);
    }

    /* Verbose */
    if (o->verbose) {
        fprintf(stderr, "Compressed [%s]: %lld B -> %lld B in %.2f sec\n",
                display, in_bytes, out_bytes, t1 - t0);
    }

    /* rm option */
    if (o->remove_source && fname && strcmp(fname, "-") != 0) {
        unlink(fname);
    }

    return 0;
}

static int process_decompress(const Options *o, const char *fname, int is_test) {
    FILE *in = NULL, *out = NULL;
    const char *display = NULL;
    if (open_input(fname, &in, &display) < 0) return 1;

    char derived[4096];
    const char *out_name = NULL;
    int out_is_devnull = 0;
    if (is_test) {
        out_is_devnull = 1;
    } else if (o->to_stdout) {
        out_name = NULL;
    } else if (o->output) {
        out_name = o->output;
    } else if (!fname || strcmp(fname, "-") == 0) {
        out_name = NULL;
    } else {
        if (derive_output_name(o, fname, derived, sizeof(derived)) < 0) {
            if (in != stdin) fclose(in);
            return 1;
        }
        out_name = derived;
    }

    if (out_is_devnull) {
        out = fopen("/dev/null", "wb");
        if (!out) { if (in != stdin) fclose(in); return 1; }
    } else if (out_name && strcmp(out_name, "-") != 0) {
        if (open_output(out_name, &out, o->force) < 0) {
            if (in != stdin) fclose(in);
            return 1;
        }
    } else {
        out = stdout;
    }

    double t0 = monotime();
    long long in_size_known = -1;
    if (in != stdin) {
        struct stat st;
        if (fstat(fileno(in), &st) == 0) in_size_known = st.st_size;
    }
    int rc = brotli_decode_stream(in, out, o->concatenated,
                                  o->large_window_set ? o->large_window : -1,
                                  o->comment_set ? o->comment_decoded : NULL,
                                  o->comment_len, o->comment_set);
    double t1 = monotime();
    long long out_bytes = 0;
    if (out != stdout) {
        out_bytes = ftell(out);
        fclose(out);
    }
    if (in != stdin) fclose(in);

    if (rc != 0) {
        fprintf(stderr, "corrupt input [%s]\n", display);
        if (out_name && out != stdout && !is_test) unlink(out_name);
        return 1;
    }

    if (fname && strcmp(fname, "-") != 0 && out != stdout && !is_test && !o->no_copy_stat) {
        copy_stat(fname, out_name);
    }

    if (o->verbose && !is_test) {
        fprintf(stderr, "Decompressed [%s]: %lld B -> %lld B in %.2f sec\n",
                display, in_size_known, out_bytes, t1 - t0);
    } else if (o->verbose && is_test) {
        fprintf(stderr, "Decompressed [%s]: %lld B -> %lld B in %.2f sec\n",
                display, in_size_known, out_bytes, t1 - t0);
    }

    if (o->remove_source && fname && strcmp(fname, "-") != 0 && !is_test) {
        unlink(fname);
    }
    return 0;
}

int main(int argc, char **argv) {
    Options o;
    opt_init(&o);

    /* Determine program basename for command aliasing */
    const char *prog = argv[0];
    const char *bn = strrchr(prog, '/');
    if (bn) bn++; else bn = prog;
    if (strcmp(bn, "brcat") == 0) {
        o.command = CMD_DECOMPRESS;
        o.command_set = 1;
        o.concatenated = 1;
        o.to_stdout = 1;
    } else if (strcmp(bn, "unbrotli") == 0) {
        o.command = CMD_DECOMPRESS;
        o.command_set = 1;
    }

    parse_args(&o, argc, argv);

    if (o.command != CMD_COMPRESS && o.quality_set) {
        die_usage("quality option only valid for compression");
    }
    if (o.command != CMD_COMPRESS && (o.lgwin_set || o.large_window_set)) {
        die_usage("window option only valid for compression");
    }

    if (o.n_files > 1 && o.output) {
        die_usage("cannot specify output file with multiple inputs");
    }

    /* If no files, treat as stdin */
    if (o.n_files == 0) {
        o.files[o.n_files++] = (char *)"-";
    }

    int overall = 0;
    for (int i = 0; i < o.n_files; i++) {
        int rc = 0;
        if (o.command == CMD_COMPRESS) {
            rc = process_compress(&o, o.files[i]);
        } else if (o.command == CMD_DECOMPRESS) {
            rc = process_decompress(&o, o.files[i], 0);
        } else if (o.command == CMD_TEST) {
            rc = process_decompress(&o, o.files[i], 1);
        }
        if (rc != 0) overall = 1;
    }
    free(o.files);
    return overall;
}
